DO $$ DECLARE n text; d text; BEGIN FOREACH n IN ARRAY ARRAY['pm_b1_redact','pm_b1_redact_proposed'] LOOP SELECT pg_get_functiondef(('public.'||n||'(jsonb,uuid,text)')::regprocedure) INTO d; d:=replace(d,'''sale_rate_snapshot'',''amount''','''sale_rate_snapshot'',''rate'',''rate_title'',''invoice_number'',''amount'''); d:=replace(d,'''notes'',''baseline_notes''','''notes'',''baseline_notes'',''content'',''raw'',''subject'''); d:=replace(d,'ELSIF k=''budget'' THEN','ELSIF k=''profit'' THEN allowed:=f AND b AND e AND s; ELSIF k=''budget'' THEN'); EXECUTE d; END LOOP; END $$;
CREATE FUNCTION public.pm_b1_stage_hours(_project uuid) RETURNS TABLE(stage_id uuid,month text,hours numeric,billable_hours numeric,non_billable_hours numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT h.* FROM public.pm_project_stage_hours(_project) h WHERE public.is_psa_staff() AND EXISTS(SELECT 1 FROM public.pm_projects p WHERE p.id=_project AND NOT p.finance_only) $$;
CREATE FUNCTION public.pm_b1_stage_locked_cost(_project uuid) RETURNS TABLE(stage_id uuid,month text,snap_cost numeric,unsnap_hours numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_psa_staff() THEN RETURN; END IF; IF NOT (public.has_role(auth.uid(),'admin') OR public.pm_can_view_projects(auth.uid()) OR public.pm_has_assigned_access(auth.uid(),_project)) THEN RETURN; END IF; IF public.pm_project_b1_active() THEN IF NOT public.pm_project_area_proposed(_project,'budget_cost',auth.uid()) THEN RETURN; END IF; ELSE IF NOT public.pm_can_see_project_financials(auth.uid()) THEN RETURN; END IF; END IF; RETURN QUERY WITH entries AS (SELECT coalesce(te.pm_stage_id,st.id,qs.id) AS sid,to_char(te.entry_date,'YYYY-MM') AS mon,te.hours AS h,te.cost_rate_snapshot AS cr FROM public.pm_time_entries te LEFT JOIN public.pm_tasks t ON t.id=te.task_id LEFT JOIN public.pm_allocations a ON a.id=t.allocation_id LEFT JOIN public.pm_stages st ON st.id=a.stage_id LEFT JOIN public.pm_stages qs ON qs.source_quote_stage_id=te.quote_stage_id AND qs.project_id=_project AND qs.stage_kind<>'retainer_month' WHERE te.entry_type='project' AND (te.pm_stage_id IN(SELECT s.id FROM public.pm_stages s WHERE s.project_id=_project) OR st.project_id=_project OR qs.id IS NOT NULL)) SELECT x.sid,x.mon,sum(CASE WHEN x.cr IS NOT NULL THEN x.h*x.cr ELSE 0 END)::numeric,sum(CASE WHEN x.cr IS NULL THEN x.h ELSE 0 END)::numeric FROM entries x WHERE x.sid IS NOT NULL GROUP BY x.sid,x.mon; END $$;
REVOKE ALL ON FUNCTION public.pm_b1_stage_hours(uuid),public.pm_b1_stage_locked_cost(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_b1_stage_hours(uuid),public.pm_b1_stage_locked_cost(uuid) TO authenticated,service_role;
COMMENT ON FUNCTION public.pm_b1_stage_locked_cost(uuid) IS 'B1 project/caller Budget-scoped saved snapshot summary; legacy summary remains inventoried for B2. No writes or snapshot estimates.';